    imageHint: "Snezka peak with chapel and post office building",
    image: "/poi-images/czechrepublic-snezka-relief-v2.webp",
    descriptionAdvanced: {
      de: "Die Schneekoppe (Sněžka) ist mit einer Höhe von 1603 Metern der höchste Gipfel des Riesengebirges und zugleich der höchste Punkt der Tschechischen Republik. Der Berg liegt direkt auf der Grenze zwischen Tschechien und Polen und ist ein markantes Symbol der Region. Geologisch besteht das Massiv überwiegend aus Glimmerschiefer und Granit, was die charakteristische Kegelform des Gipfels erklärt. Auf dem Gipfel befinden sich mehrere Bauwerke, darunter die barocke Laurentiuskapelle aus dem Jahr 1681 und das moderne tschechische Postamt, welches das höchstgelegene des Landes ist. Aufgrund der exponierten Lage herrscht auf der Schneekoppe ein raues alpines Klima mit niedrigen Durchschnittstemperaturen und starken Winden. Der Berg ist ein beliebtes Ziel für Wanderer und kann auch bequem mit einer Seilbahn von Pec pod Sněžkou aus erreicht werden. Bei klarer Sicht reicht der Blick bis weit nach Böhmen und Schlesien.",
      hu: "A Sněžka 1603 méteres magasságával az Óriás-hegység (Krkonoše) és egyben Csehország legmagasabb hegycsúcsa. A hegy közvetlenül a cseh-lengyel határon fekszik, és a régió egyik legfontosabb turisztikai jelképe. Geológiailag főként csillámpalából épül fel, amely a csúcs jellegzetes, háromoldalú gúla alakját adja. A hegytetőn több épület is található, köztük az 1681-ben épült barokk Szent Lőrinc-kápolna, valamint a modern cseh postahivatal, amely az ország legmagasabban fekvő postája. A Sněžka éghajlata rendkívül zord, az éves átlaghőmérséklet alig haladja meg a 0 Celsius-fokot, és gyakoriak az erős szélviharok. A csúcsra több kijelölt turistaút vezet, de a látogatók Pec pod Sněžkou városából induló drótkötélpályás felvonóval is feljuthatnak. A kilátás tiszta időben messze benyúlik a Cseh-medencébe és a lengyelországi Sziléziába.",
      ro: "Sněžka, cu o altitudine de 1603 metri, este cel mai înalt vârf din munții Krkonoše și cel mai înalt punct din Republica Cehă. Muntele este situat exact pe granița dintre Cehia și Polonia, fiind un simbol proeminent al peisajului alpin din Europa Centrală. Din punct de vedere geologic, masivul este format în principal din șisturi cristaline și granit, ceea ce îi conferă forma sa conică distinctivă. Pe vârf se află mai multe structuri istorice și moderne, printre care capela barocă Sfântul Laurențiu, construită în 1681, și cel mai înalt oficiu poștal din țară. Clima de pe Sněžka este aspră, cu temperaturi medii scăzute și vânturi puternice care pot atinge viteze de uragan. Accesul pe vârf se poate face prin numeroase trasee de drumeție sau cu ajutorul unei telecabine moderne care pornește din localitatea Pec pod Sněžkou, oferind panorame asupra Boemiei și Sileziei.",
      en: "Sněžka, reaching an elevation of 1,603 meters, is the highest peak in the Giant Mountains (Krkonoše) and the highest point in the Czech Republic. The mountain sits directly on the border between the Czech Republic and Poland, serving as a prominent landmark in Central Europe. Geologically, the massif is primarily composed of mica schists and granite, which accounts for the peak's characteristic pyramidal shape. Several buildings occupy the summit, including the Baroque Chapel of St. Lawrence dating back to 1681 and a modern Czech post office, which is the highest in the country. Due to its exposed position, Sněžka experiences a harsh alpine climate with low average temperatures and frequent gale-force winds. The summit is a popular destination for hikers and is also accessible via a cable car from the town of Pec pod Sněžkou, providing expansive views across Bohemia and Silesia.",
      es: "Sněžka es, con una altura de 1603 metros, el pico más alto de las montañas Krkonoše (Riesengebirge) y al mismo tiempo el punto más alto de la República Checa. La montaña se encuentra directamente en la frontera entre Chequia y Polonia y es un símbolo distintivo de la región. Geológicamente, el macizo está compuesto principalmente por micaesquisto y granito, lo que explica la característica forma cónica de la cima. En la cima se encuentran varias construcciones, entre ellas la capilla barroca de San Lorenzo de 1681 y la moderna oficina de correos checa, que es la más alta del país. Debido a su ubicación expuesta, en Sněžka predomina un duro clima alpino con temperaturas medias bajas y vientos fuertes. La montaña es un destino popular para los excursionistas y también se puede llegar cómodamente en teleférico desde Pec pod Sněžkou. En días claros, la vista se extiende hasta gran parte de Bohemia y Silesia.",
      pt: "A Sněžka, com uma altitude de 1603 metros, é o pico mais alto das montanhas Krkonoše e, simultaneamente, o ponto mais alto da República Checa. A montanha situa-se diretamente na fronteira entre a República Checa e a Polónia e é um símbolo marcante da região. Geologicamente, o maciço é composto principalmente por micaxisto e granito, o que explica a característica forma cónica do topo. No topo encontram-se vários edifícios, incluindo a capela barroca de São Lourenço de 1681 e a moderna estação de correios checa, que é a mais alta do país. Devido à sua localização exposta, reina na Sněžka um clima alpino rigoroso, com baixas temperaturas médias e ventos fortes. A montanha é um destino popular para caminhantes e pode também ser alcançada confortavelmente através de um teleférico a partir de Pec pod Sněžkou. Com boa visibilidade, a vista estende-se até bem longe na Boêmia e na Silésia.",
      fr: "La Sněžka, culminant à 1603 mètres, est le point culminant des monts des Géants et de la République tchèque. Elle se situe précisément sur la frontière entre la Tchéquie et la Pologne, constituant un symbole fort de la région. Géologiquement, le massif est principalement formé de micaschiste et de granite, ce qui explique la forme conique caractéristique de son sommet. On y trouve plusieurs édifices, dont la chapelle baroque Saint-Laurent datant de 1681 et le bureau de poste tchèque moderne, le plus haut du pays. En raison de sa position exposée, la Sněžka connaît un climat alpin rude, marqué par des températures moyennes basses et des vents violents. Destination prisée des randonneurs, elle est également accessible par un téléphérique partant de Pec pod Sněžkou. Par temps clair, le panorama s'étend sur une grande partie de la Bohême et de la Silésie.",
    },
