      de: ["Höhe beträgt 1491 Meter über dem Meeresspiegel", "Fernseh- und Aussichtsturm ist 162 Meter hoch", "Plattform befindet sich auf 1563 Metern Höhe", "Nationales Naturreservat seit dem Jahr 1955", "Durchschnittliche Schneebedeckung dauert 160 Tage", "Bau des heutigen Turms begann im Jahr 1968"],
