      pt: ["A altitude é de 1491 metros acima do nível do mar", "A torre de televisão e observação tem 162 metros", "A plataforma situa-se a 1563 metros de altitude", "Reserva Natural Nacional desde o ano de 1955", "A cobertura de neve dura em média 160 dias", "A construção da torre atual começou em 1968"],
      fr: ["Altitude de 1491 mètres au-dessus du niveau de la mer", "La tour de télévision et d'observation mesure 162 mètres", "La plateforme se situe à 1563 mètres d'altitude", "Réserve naturelle nationale depuis l'année 1955", "L'enneigement moyen dure 160 jours par an", "La construction de la tour actuelle a débuté en 1968"],
