      hu: ["Magassága 1378 méter a tengerszint felett", "A Plešné-tó 1090 méter magasan fekszik", "A Stifter-emlékmű összesen 14,5 méter magas", "Közvetlenül a cseh-osztrák határon található", "A Šumava Nemzeti Park központi részéhez tartozik", "A Cseh-erdő legmagasabb csúcsa a cseh oldalon"],
