      en: ["Elevation is 1,378 meters above sea level", "Glacial Lake Plešné is situated at 1,090 meters", "Stifter monument is 14.5 meters high total", "Located directly on the Czech-Austrian border", "Part of the Šumava National Park core zone", "Highest peak in the Bohemian Forest on the Czech side"],
      es: ["La altitud es de 1378 metros sobre el nivel del mar", "El lago glaciar Plešné jezero está a 1090 metros", "El monumento a Stifter tiene una altura total de 14,5 metros", "Se sitúa directamente en la frontera checo-austríaca", "Pertenece a la zona núcleo del Parque Nacional Šumava", "Pico más alto de la Selva de Bohemia en el lado checo"],
      pt: ["A altitude é de 1378 metros acima do nível do mar", "O lago glaciar Plešné jezero situa-se a 1090 metros", "O monumento a Stifter tem uma altura total de 14,5 metros", "Situa-se diretamente na fronteira checo-austríaca", "Pertence à zona central do Parque Nacional Šumava", "Cume mais alto da Selva da Boémia no lado checo"],
