    description: {
      de: "Der Große Jauerling ist mit 970 Metern der höchste Berg der Weißen Karpaten. Er ist ein Symbol der tschechisch-slowakischen Verbundenheit und beherbergt einen bedeutenden Sendemast.",
      hu: "A Velká Javořina a Fehér-Kárpátok legmagasabb csúcsa, 970 méter magas. A cseh-szlovák barátság szimbóluma, ahol rendszeresen közös kulturális találkozókat tartanak.",
      ro: "Velka Javorina este cel mai înalt vârf din Carpații Albi, atingând 970 metri. Este un simbol al frăției ceho-slovace, situat exact pe granița dintre cele două țări.",
      en: "Velka Javorina is the highest peak of the White Carpathians, standing at 970 meters. It serves as a symbol of Czech-Slovak unity and hosts regular joint cultural events.",
      es: "Velká Javorina es, con 970 metros, la montaña más alta de los Cárpatos Blancos. Es un símbolo de la unión checo-eslovaca y alberga una importante torre de telecomunicaciones.",
      pt: "Velká Javorina é, com 970 metros, a montanha mais alta dos Cárpatos Brancos. É um símbolo da união checo-eslovaca e alberga uma importante torre de telecomunicações.",
      fr: "Velká Javorina est, avec 970 mètres, le point culminant des Carpates blanches. Symbole du lien entre Tchèques et Slovaques, elle abrite un important pylône émetteur.",
    },
