      pt: ["Pico mais alto Praděd (1491 m)", "CHKO Jeseníky fundada em 1969", "Central de bombagem Dlouhé stráně a 1350 m s.n.m.", "Torre de televisão Praděd tem 146,5 m de altura", "Karlova Studánka, estância termal mais elevada", "Segunda cordilheira mais alta da República Checa"],
      fr: ["Point culminant Praděd (1 491 m)", "CHKO Jeseníky créée en 1969", "Centrale de Dlouhé stráně à 1 350 m d'altitude", "La tour de télévision du Praděd mesure 146,5 m", "Karlova Studánka est la cure thermale la plus haute", "Deuxième plus haut massif de République tchèque"],
