      en: ["Highest peak Milešovka 837m", "Volcanic origin from the Tertiary period", "CHKO established in 1976", "Porta Bohemica gorge valley", "Area approximately 1,063 square kilometers", "Milešovka is the windiest place in the CZ"],
      es: ["Pico más alto: Milešovka (837 m)", "Origen volcánico en el Terciario", "Área protegida (CHKO) fundada en 1976", "Valle de ruptura Porta Bohemica", "Superficie aprox. 1.063 km²", "Milešovka es el lugar más ventoso de CZ"],
      pt: ["Pico mais alto: Milešovka (837 m)", "Origem vulcânica no Terciário", "Área protegida (CHKO) fundada em 1976", "Vale de rutura Porta Bohemica", "Área de aprox. 1.063 km²", "Milešovka é o local mais ventoso da CZ"],
      fr: ["Point culminant Milešovka (837 m)", "Origine volcanique au Tertiaire", "CHKO créée en 1976", "Gorge de la Porta Bohemica", "Superficie d'environ 1 063 km²", "Milešovka est l'endroit le plus venteux de Tchéquie"],
