      es: ["Altura de 1084 metros sobre el mar", "Torre de piedra más antigua (1825)", "Observatorio fundado en 1957", "Longitud del telesilla 1752 metros", "La torre de televisión mide 172 metros de alto", "Visibilidad hasta los Alpes"],
      pt: ["Altitude 1084 metros acima do mar", "Torre de pedra mais antiga (1825)", "Observatório fundado em 1957", "Comprimento do teleférico 1752 metros", "A torre de televisão tem 172 metros de altura", "Visibilidade até aos Alpes"],
      fr: ["Altitude de 1084 mètres au-dessus de la mer", "Plus ancienne tour en pierre (1825)", "Observatoire fondé en 1957", "Longueur du télésiège : 1752 mètres", "La tour de télévision mesure 172 mètres de haut", "Portée visuelle jusqu'aux Alpes"],
