      en: ["Highest peak Brdo 587m", "Part of the Outer Western Carpathians", "Buchlov Castle since the 13th century", "Brdo lookout tower built in 2004", "Velehrad is a major pilgrimage site", "Kazatelna sandstone formation"],
      es: ["Pico más alto: Brdo (587 m)", "Parte de los Cárpatos Occidentales Exteriores", "Castillo de Buchlov desde el siglo XIII", "Torre de observación Brdo construida en 2004", "Velehrad, importante lugar de peregrinación", "Formación de arenisca Kazatelna"],
      pt: ["Pico mais alto: Brdo (587 m)", "Parte dos Cárpatos Ocidentais Exteriores", "Castelo de Buchlov desde o século XIII", "Torre de observação Brdo construída em 2004", "Velehrad, importante local de peregrinação", "Formação de arenito Kazatelna"],
      fr: ["Point culminant Brdo (587 m)", "Fait partie des Carpates occidentales extérieures", "Château de Buchlov datant du XIIIe siècle", "Tour d'observation du Brdo construite en 2004", "Velehrad, haut lieu de pèlerinage", "Formation de grès Kazatelna"],
