      en: ["Highest peak is Kelčský Javorník", "Important Catholic pilgrimage center", "Wooden lookout towers on summits", "Dense beech forests"],
      es: ["El pico más alto es el Kelčský Javorník", "Importante centro de peregrinación católica", "Torres de observación de madera en las cimas", "Densos bosques de hayas"],
